@pytest.mark.parametrize("text", ["1.8.0", "1-0:1.8.0", "1.0.1.8.0.256", "-1.0.1.8.0.255", "1.0.1.8.0.255x"])
def test_bad_obis(text):
    with pytest.raises(dlms.PowerDLMSError):
        dlms.parse_obis(text)


def test_wrong_types_and_budget_contract():
    for parser in (dlms.parse_axdr, dlms.parse_apdu, dlms.parse_wrapper, dlms.parse_wrapper_stream):
        for bad in (None, 1, "", [], {}, True):
            with pytest.raises(dlms.PowerDLMSError):
                parser(bad)
    for bad in (None, 1, [], b"\x01"):
        with pytest.raises(dlms.PowerDLMSError):
            dlms.parse_obis(bad)
    with pytest.raises(dlms.PowerDLMSError):
        dlms.parse_axdr(b"\x01\x01" * 34 + b"\x00")
    with pytest.raises(dlms.PowerDLMSError):
        dlms.parse_apdu(b"\x00" * (dlms.MAX_INPUT + 1))
    with pytest.raises(dlms.PowerDLMSError):
        dlms.parse_wrapper_stream(REQUEST + b"\x00")
    with pytest.raises(dlms.PowerDLMSError):
        dlms.parse_wrapper(b"\x00\x02" + REQUEST[2:])
    with pytest.raises(dlms.PowerDLMSError):
        dlms.parse_wrapper_stream(b"")


def test_memoryview_byte_budget_and_released_view(monkeypatch):
    monkeypatch.setattr(dlms, "MAX_INPUT", 16)
    view = memoryview(array("I", [0] * 5))
    assert len(view) < 16 < view.nbytes
    with pytest.raises(dlms.PowerDLMSError):
        dlms.parse_axdr(view)
    view.release()
    with pytest.raises(dlms.PowerDLMSError):
        dlms.parse_apdu(view)


def test_deterministic_malformed_bytes_never_leak_exception():
    rng = random.Random(61850)
    for _ in range(1500):
        raw = rng.randbytes(rng.randrange(0, 96))
        for parser in (dlms.parse_axdr, dlms.parse_apdu, dlms.parse_wrapper):
            try:
                parser(raw)
            except dlms.PowerDLMSError:
                pass


def test_cli(tmp_path, capsys, monkeypatch):
    sample = tmp_path / "meter.bin"
    sample.write_bytes(RESPONSE)
    assert dlms.main([str(sample)]) == 0
    assert '"double-long-unsigned"' in capsys.readouterr().out
    sample.write_text(RESPONSE.hex())
    assert dlms.main([str(sample), "--hex"]) == 0
    assert dlms.main(["1-0:32.7.0*255", "--format", "obis"]) == 0
    assert dlms.main([str(tmp_path / "missing")]) == 2
    sample.write_text("gg")
    assert dlms.main([str(sample), "--hex"]) == 2
    assert dlms.main(["--help"]) == 0
    assert dlms.main(["--bad-option"]) == 2
    def unusual_exit(*args, **kwargs):
        raise SystemExit("error")
    monkeypatch.setattr(argparse.ArgumentParser, "parse_args", unusual_exit)
    assert dlms.main([]) == 2
